// Employment Contracts → Word (.doc) & PDF theme engine.
// This perfectly mirrors the CV module's unified architectural identities,
// ensuring that contracts and CVs generated by the platform share the exact
// same design language, typography, and visual aura.

export type DocumentTheme = 'corporate' | 'legal' | 'modern' | 'minimal' | 'letterhead' | 'editorial';
export type BrandingStrategy = 'embedded' | 'company_letterhead' | 'theme_header' | 'none';

export interface ContractThemeSettings {
  theme: DocumentTheme;
  primaryColor: string;
  accentColor: string;
  fontFamily: string;
  fontScale: 0.9 | 1 | 1.1;
  brandingStrategy: BrandingStrategy;
}

// Strictly binds a single font family per layout to completely standardize the document's aesthetic,
// mirroring the CV STRICT_FONT_MAP exactly.
export const THEME_DEFAULTS: Record<DocumentTheme, { primaryColor: string; accentColor: string; fontFamily: string; label: string; description: string }> = {
  corporate: { primaryColor: '#0a3d7d', accentColor: '#178ac7', fontFamily: "Arial, Helvetica, sans-serif", label: 'Corporate', description: 'Professional, structured, Fortune 500 styling' },
  legal: { primaryColor: '#000000', accentColor: '#000000', fontFamily: '"Times New Roman", Times, serif', label: 'Legal', description: 'Traditional, double-spaced, strict execution copy' },
  modern: { primaryColor: '#111827', accentColor: '#4f46e5', fontFamily: '"Helvetica Neue", Helvetica, Arial, sans-serif', label: 'Modern', description: 'Sleek geometric typography, soft styling' },
  minimal: { primaryColor: '#111111', accentColor: '#666666', fontFamily: 'system-ui, -apple-system, sans-serif', label: 'Minimal', description: 'Ultra-clean, whitespace-heavy, distraction-free' },
  letterhead: { primaryColor: '#1a3a5f', accentColor: '#b08a3e', fontFamily: 'Calibri, Arial, sans-serif', label: 'Letterhead', description: 'Subtle classic stationery style with elegant headings' },
  editorial: { primaryColor: '#7c2d12', accentColor: '#c2703d', fontFamily: 'Georgia, "Times New Roman", serif', label: 'Editorial', description: 'Magazine-esque, beautiful serifs, highly legible' },
};

export const DEFAULT_CONTRACT_THEME: ContractThemeSettings = {
  theme: 'corporate',
  primaryColor: THEME_DEFAULTS.corporate.primaryColor,
  accentColor: THEME_DEFAULTS.corporate.accentColor,
  fontFamily: THEME_DEFAULTS.corporate.fontFamily,
  fontScale: 1,
  brandingStrategy: 'theme_header',
};

import { COLOR_PRESETS, toWordSafeFontStack, makeCssWordSafe } from '@/lib/documentTheme';
export { COLOR_PRESETS, toWordSafeFontStack };

// Available to users if they want to override the strict defaults
export const FONT_OPTIONS = [
  { name: 'Arial', family: 'Arial, Helvetica, sans-serif', desc: 'Standard Corporate' },
  { name: 'Helvetica Neue', family: '"Helvetica Neue", Helvetica, Arial, sans-serif', desc: 'Clean Modern' },
  { name: 'System', family: 'system-ui, -apple-system, sans-serif', desc: 'Minimalist Sans' },
  { name: 'Calibri', family: 'Calibri, Arial, sans-serif', desc: 'Classic Letterhead' },
  { name: 'Times New Roman', family: '"Times New Roman", Times, serif', desc: 'Strict Legal' },
  { name: 'Georgia', family: 'Georgia, "Times New Roman", serif', desc: 'Elegant Serif' },
];

type ThemeCssArgs = { primaryColor: string; accentColor: string; fontFamily: string; fontScale: number };

const BASE_SECTION_STYLES = `
  .cs-section, .cs-section * { white-space: normal; }
  .cs-section { margin-bottom: 16px; }
  .cs-section:last-child { margin-bottom: 0; }
  .cs-missing-clause { color: #b91c1c; font-style: italic; border: 1px dashed #b91c1c; padding: 10px 14px; border-radius: 4px; }
  .cs-section p { margin-bottom: 8px; }
  /* Tailwind's Preflight base reset strips list-style/margin/padding from
     every ul/ol globally - restore real bullets/numbers here since this is
     contract prose, not app UI chrome. */
  .cs-section ul { list-style-type: disc; margin-bottom: 8px; padding-left: 20px; }
  .cs-section ol { list-style-type: decimal; margin-bottom: 8px; padding-left: 20px; }
  .cs-section li { display: list-item; margin-bottom: 4px; }
  .cs-section h1 { margin-bottom: 16px; }
  .cs-section h2 { margin-top: 4px; margin-bottom: 8px; }
  .cs-section h3 { margin-top: 10px; margin-bottom: 6px; }
  .cs-section .signature-block { margin-top: 28px; }
  [data-section="appendix_job_description"] { page-break-before: always; }
  [data-section="signatures"] { page-break-inside: avoid; }
  .cs-section-heading { margin-top: 20px; margin-bottom: 8px; }

  /* Highlights which entity a resolved placeholder value came from */
  .ph-entity-company { background: #dbeafe; border-radius: 3px; padding: 0 3px; }
  .ph-entity-employee { background: #dcfce7; border-radius: 3px; padding: 0 3px; }
  .ph-entity-missing { opacity: 0.55; font-style: italic; }
`;

